Inside the body of this function, what is the type of `title`?

```ts
function greet(name: string, title?: string) {
  // ...
}
```

Which call is a compile error?

```ts
function sum(...nums: number[]) {
  return nums.reduce((a, b) => a + b, 0);
}
```

What does this constructor do?

```ts
class Person {
  constructor(public name: string, private age: number) {}
}
```

What does this log when the compiled JavaScript runs?

```ts
class Account {
  private pin = 1234;
  #token = "abc";
}
const a = new Account();
console.log((a as any).pin, Object.keys(a));
```

What happens when you compile this?

```ts
abstract class Shape {
  abstract area(): number;
}
const s = new Shape();
```

Which statement is true about this code?

```ts
const handler: () => void = () => 42;
const result = handler();
```

What does TypeScript report for the last line, and what is the usual fix?

```ts
function len(s: string): number;
function len(a: any[]): number;
function len(x: string | any[]) { return x.length; }

len(Math.random() > 0.5 ? "hi" : [1]);
```

What does TypeScript report for the second line?

```ts
function greet(this: { name: string }) { return this.name; }
greet();
```

Which statement is true?

```ts
function f(x?: number) {}
function g(x: number | undefined) {}

f();
g();
```

What does TypeScript report for the last line?

```ts
class Counter {
  static count = 0;
}
const c = new Counter();
c.count;
```

What is the type of `r`?

```ts
function f(x: unknown): string;
function f(x: number): number;
function f(x: unknown) { return x as any; }

const r = f(1);
```

The last line fails with "Property 'extra' does not exist on type 'Builder'". Which change makes the chain compile without any casts?

```ts
class Builder {
  set(key: string): Builder { return this; }
}
class Sub extends Builder {
  extra() { return this; }
}
new Sub().set("a").extra();
```

This compiles with `--noImplicitOverride`. Which two statements are true? (Choose two.)

```ts
class A { run() {} }
class B extends A {
  run() {}            // line 3
  override walk() {}  // line 4
}
```

Consider this class. Which three statements are true? (Choose three.)

```ts
class Vault {
  private secret = 1;
  #hidden = 2;
  static check(o: object) { return #hidden in o; }
}
const v = new Vault();
```

Under `strict`, this reports TS2564 on `name`. Why?

```ts
class Config {
  name: string;
  constructor() { this.init(); }
  init() { this.name = "default"; }
}
```

Which statement is true about this code (TypeScript 5.1 or later)?

```ts
class Temperature {
  #celsius = 0;
  get value(): number { return this.#celsius; }
  set value(v: number | string) { this.#celsius = Number(v); }
}
const t = new Temperature();
t.value = "21";
const n = t.value;
```

What does TypeScript report for the last line, and why?

```ts
type Ctor<T> = new (...args: any[]) => T;
function make<T>(C: Ctor<T>) { return new C(); }

abstract class Shape {}
make(Shape);
```

With `target: "ES2022"` (so class fields use define semantics), put the steps of `new Derived(7)` in the order they happen.

```ts
class Base {
  b = initB();
  constructor() { console.log("base body"); }
}
class Derived extends Base {
  d = initD();
  constructor(public id: number) {
    super();
    console.log("derived body");
  }
}
```

Why does the last line error, and what is the better declaration?

```ts
declare function each(
  arr: number[],
  cb: (value: number, index?: number) => void
): void;

each([1, 2], (v, i) => console.log(i.toFixed()));
```

Which two statements about this mixin are true? (Choose two.)

```ts
type Constructor = new (...args: any[]) => {};

function Timestamped<TBase extends Constructor>(Base: TBase) {
  return class extends Base { ts = Date.now(); };
}

class User { name = "u"; }
const TimestampedUser = Timestamped(User);
const x = new TimestampedUser();
```

What is the type of `r`?

```ts
function pick(x: "a"): 1;
function pick(x: "b"): 2;
function pick(x: string): number;
function pick(x: string) { return 0 as any; }

declare const k: "a" | "b";
const r = pick(k);
```

What happens when this compiles and runs (the class body is in strict mode)?

```ts
class Counter {
  n = 0;
  inc(this: Counter) { this.n++; }
}
const c = new Counter();
const later: () => void = c.inc;
later();
```

What is `P`?

```ts
class Point {
  constructor(public x: number, y?: string) {}
}
type P = ConstructorParameters<typeof Point>;
```

With `target: "ES2022"` and `strict`, what happens here?

```ts
class Base { name = "base"; }
class D1 extends Base { name!: string; }
class D2 extends Base { declare name: string; }
```

What does this log, and what does TypeScript say about it?

```ts
abstract class Base {
  constructor() { console.log(this.describe()); }
  abstract describe(): string;
}
class Impl extends Base {
  label = "impl";
  describe() { return this.label; }
}
new Impl();
```

Which statement is true?

```ts
class Money {
  doubled = this.amount * 2;
  constructor(public amount: number) {}
}
```

Under `strict` (`noImplicitAny`), what does TypeScript report for this function?

```ts
function fact(n: number) {
  return n <= 1 ? 1 : n * fact(n - 1);
}
```

TypeScript 5 standard decorators. Put the console output of this class definition in order.

```ts
function dec(name: string) {
  console.log("eval " + name);
  return function (target: any, ctx: ClassMethodDecoratorContext) {
    console.log("apply " + name);
    return target;
  };
}
class Service {
  @dec("A") @dec("B") run() {}
}
```
